from rdkit import Chem
import numpy as np
m=Chem.MolFromMolFile('lig3d.mol',removeHs=False)
c=m.GetConformer().GetPositions()
for b in m.GetBonds():
    i,j=b.GetBeginAtomIdx(),b.GetEndAtomIdx()
    d=np.linalg.norm(c[i]-c[j])
    if d>2.0 or d<0.9: print(i,m.GetAtomWithIdx(i).GetSymbol(),j,m.GetAtomWithIdx(j).GetSymbol(),round(d,3))
print('min nonbonded:')
bs=set()
for b in m.GetBonds(): bs.add((b.GetBeginAtomIdx(),b.GetEndAtomIdx()))
n=len(c); mind=9
for i in range(n):
  for j in range(i+1,n):
    if (i,j) in bs or (j,i) in bs: continue
    d=np.linalg.norm(c[i]-c[j])
    if d<mind: mind=d; pr=(i,j)
print(mind,pr)
"
